/**
 * Export the three platforms that need no API key at all: landing-page, slideshare, rss.
 *
 * These three were listed in the platform spec as things to publish to, and none of them is
 * actually a network destination. A landing page is a file a static host serves, a slide deck is a
 * document somebody uploads by hand, and the RSS feed is generated by the site itself. Treating
 * them as API targets was the reason they sat behind a credential that will never exist.
 *
 * ## Deduplication is the substantive decision here
 *
 * The renderer runs every platform through three viewpoints, and these three ignore the viewpoint:
 * naming a category the same way for a decision-maker and a practitioner produces identical text.
 * Landing page alone has 309 rendered files for 103 distinct questions. Exporting all of them would
 * publish 309 pages to a host where 103 exist, which is the duplicate-content pattern this site
 * spends its effort avoiding everywhere else.
 *
 * So the export is keyed on the content hash rather than the file path. Duplicates collapse, and
 * the manifest records how many collapsed, because "how many did we not write" is the number that
 * would otherwise be invisible.
 *
 * ## What is written
 *
 *   exports/landing-pages/<slug>.html   one page per distinct question, self-contained
 *   exports/landing-pages/index.json    the manifest: slug, question, canonical, retrieval date
 *   exports/slideshare/<slug>.md        one deck outline per article, slides in order
 *   exports/slideshare/index.json       the manifest
 *   exports/rss/README.md               why RSS is not exported here
 *   exports/MANIFEST.json               everything, with counts and dedup figures
 *
 * Everything under `exports/` is generated and ignored by git, the same as `data/renders/`: it is
 * reproducible from the atom pool by running this tool.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, rmSync } from "node:fs";
import { join, dirname } from "node:path";
import { createHash } from "node:crypto";

const ROOT = process.cwd();
const RENDERS = join(ROOT, "data", "renders");
const OUT = join(ROOT, "exports");
const SITE = "https://landedmath.com";

const args = process.argv.slice(2);
const DRY = args.includes("--dry-run");

/** Read every rendered file for a platform, across all viewpoints. */
function readPlatform(platform) {
  const base = join(RENDERS, platform);
  if (!existsSync(base)) return [];
  const out = [];
  for (const vp of readdirSync(base)) {
    const dir = join(base, vp);
    let files = [];
    try {
      files = readdirSync(dir).filter((f) => f.endsWith(".txt")).sort();
    } catch {
      continue;
    }
    for (const f of files) {
      out.push({ viewpoint: vp, file: f, text: readFileSync(join(dir, f), "utf8") });
    }
  }
  return out;
}

const esc = (s) =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

const slugify = (s) =>
  String(s)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 72);

const hash = (s) => createHash("sha256").update(s).digest("hex").slice(0, 12);

/**
 * A landing page, as a standalone document.
 *
 * Self-contained on purpose: no stylesheet link, no font, no script. These are pages whose whole
 * job is to be read by a search engine and a person arriving from one, and a page that depends on
 * the main site's build to look right is a page that breaks the first time it is served elsewhere.
 * The inline style is deliberately minimal and the numbers are all in the text.
 */
function landingPageHtml(r) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(r.h1)} — Landed Math</title>
<meta name="description" content="${esc(r.answer.slice(0, 155))}">
<link rel="canonical" href="${esc(r.canonical)}">
<meta property="og:title" content="${esc(r.h1)}">
<meta property="og:description" content="${esc(r.answer.slice(0, 155))}">
<meta property="og:type" content="article">
<style>
:root{--ink:#101418;--ink2:#38414a;--line:#dfe3e8;--red:#b3261e}
*{box-sizing:border-box}
body{margin:0;font:16px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:var(--ink)}
main{max-width:44rem;margin:0 auto;padding:40px 20px 72px}
h1{font-size:1.6rem;line-height:1.3;margin:0 0 22px}
p{margin:0 0 18px;color:var(--ink2)}
.meta{margin-top:36px;padding-top:18px;border-top:1px solid var(--line);font-size:13.5px;color:#5b6672}
a{color:var(--red)}
</style>
</head>
<body>
<main>
<h1>${esc(r.h1)}</h1>
<p>${esc(r.answer)}</p>
<div class="meta">
<p>Figures retrieved ${esc(r.retrieved)}. Every number on this page is traceable to a named document, and the sources and the working are in the analysis.</p>
<p><a href="${esc(r.canonical)}">Read the full analysis, with every source and date &rarr;</a></p>
<p>Landed Math publishes what Chinese customs, tax and trade documents change for importers, with the arithmetic shown.</p>
</div>
</main>
</body>
</html>
`;
}

/* ------------------------------------------------------------------ parse */

function parseLanding(text) {
  const g = (k) => new RegExp(`^${k}:\\s*(.*)$`, "m").exec(text)?.[1]?.trim() ?? "";
  return {
    h1: g("H1"),
    answer: g("ANSWER"),
    retrieved: g("RETRIEVED"),
    category: g("CATEGORY"),
    canonical: g("SOURCES AND WORKING"),
  };
}

function parseSlideshare(text) {
  const slides = [...text.matchAll(/^SLIDE (\d+) — ([\s\S]*?)(?=\n\nSLIDE |\n\nLAST SLIDE|$)/gm)].map((m) => ({
    n: Number(m[1]),
    body: m[2].trim(),
  }));
  const last = /^LAST SLIDE — ([\s\S]*)$/m.exec(text)?.[1]?.trim() ?? "";
  const title = slides[0]?.body.split("\n")[0] ?? "";
  const canonical = /(https:\/\/landedmath\.com\/\S+)/.exec(text)?.[1] ?? "";
  return { slides, last, title, canonical };
}

/* ------------------------------------------------------------------ run */

const report = { landingPages: {}, slideshare: {}, rss: {} };
const dedupStats = {};

if (!DRY) {
  rmSync(OUT, { recursive: true, force: true });
  mkdirSync(join(OUT, "landing-pages"), { recursive: true });
  mkdirSync(join(OUT, "slideshare"), { recursive: true });
  mkdirSync(join(OUT, "rss"), { recursive: true });
}

/* ---- landing pages ---- */
{
  const rows = readPlatform("landing-page").map((x) => ({ ...x, parsed: parseLanding(x.text) }));
  const seen = new Map();
  let collapsed = 0;
  const manifest = [];
  for (const r of rows) {
    const p = r.parsed;
    if (!p.h1 || !p.answer || p.answer.startsWith("[")) continue;
    const key = hash(`${p.h1}\u0000${p.answer}`);
    if (seen.has(key)) {
      collapsed++;
      continue;
    }
    seen.set(key, true);
    const slug = slugify(p.h1);
    manifest.push({
      slug,
      question: p.h1,
      retrieved: p.retrieved,
      category: p.category,
      canonical: p.canonical,
      words: p.answer.split(/\s+/).length,
    });
    if (!DRY) writeFileSync(join(OUT, "landing-pages", `${slug}.html`), landingPageHtml(p), "utf8");
  }
  if (!DRY) writeFileSync(join(OUT, "landing-pages", "index.json"), JSON.stringify({ pages: manifest }, null, 2), "utf8");
  dedupStats.landingPages = { rendered: rows.length, distinct: manifest.length, collapsed };
  report.landingPages = { files: manifest.length, collapsed };
}

/* ---- slideshare ---- */
{
  const rows = readPlatform("slideshare");
  const byArticle = new Map();
  let collapsed = 0;
  for (const r of rows) {
    const s = parseSlideshare(r.text);
    if (!s.slides.length) continue;
    const key = s.canonical || s.title;
    if (byArticle.has(key)) {
      collapsed++;
      continue;
    }
    byArticle.set(key, s);
  }
  const manifest = [];
  for (const [key, s] of byArticle) {
    const slug = slugify(s.title) || hash(key);
    const md = [
      `# ${s.title}`,
      "",
      `${s.slides.length} slides. Every figure below is traceable to a named document with a retrieval date.`,
      "",
      ...s.slides.map((x) => `## Slide ${x.n}\n\n${x.body}\n`),
      s.last ? `## Closing slide\n\n${s.last}\n` : "",
      `---`,
      "",
      `Source and working: ${s.canonical}`,
      "",
    ].join("\n");
    manifest.push({ slug, title: s.title, slides: s.slides.length, canonical: s.canonical });
    if (!DRY) writeFileSync(join(OUT, "slideshare", `${slug}.md`), md, "utf8");
  }
  if (!DRY) writeFileSync(join(OUT, "slideshare", "index.json"), JSON.stringify({ decks: manifest }, null, 2), "utf8");
  dedupStats.slideshare = { rendered: rows.length, distinct: manifest.length, collapsed };
  report.slideshare = { files: manifest.length, collapsed };
}

/* ---- rss: explained, not exported ---- */
{
  const note = `# RSS is not exported here

The \`rss\` platform in \`config/platform-spec.json\` is not a destination. It is a placeholder for a
feed the site already generates, and the Astro endpoint is the thing that publishes it:

    src/pages/rss.xml.ts   ->   https://landedmath.com/rss.xml

The renderer carries the string "handled by src/pages/rss.xml.ts — not rendered here" for the same
reason: there is nothing to send and no credential to wait for. Writing a second feed here would
produce two feeds whose item sets could drift apart, and a subscriber would be reading whichever
one they happened to add.

If the feed itself needs changing, change the endpoint. This directory exists so the export report
does not silently omit one of the three platforms that was approved for export.
`;
  if (!DRY) writeFileSync(join(OUT, "rss", "README.md"), note, "utf8");
  report.rss = { endpoint: `${SITE}/rss.xml`, exported: false, reason: "generated by the site, see exports/rss/README.md" };
}

/* ---- manifest ---- */
{
  const manifest = {
    generatedAt: new Date().toISOString(),
    note: "Generated by tools/export.mjs. Everything here is reproducible from data/atoms/; nothing in exports/ is tracked by git.",
    deduplication: dedupStats,
    platforms: report,
    wire: [
      "landing-pages/*.html  -> any static host; each page is self-contained and carries its canonical link",
      "slideshare/*.md       -> upload by hand, or convert to .pptx before uploading",
      "rss                   -> already live at the endpoint above; nothing to upload",
    ],
  };
  if (!DRY) writeFileSync(join(OUT, "MANIFEST.json"), JSON.stringify(manifest, null, 2), "utf8");
}

/* ------------------------------------------------------------------ report */

console.log(`EXPORT${DRY ? " (dry run)" : ""}\n${"=".repeat(74)}`);
console.log(`  landing-pages  ${String(report.landingPages.files).padStart(4)} files   (from ${dedupStats.landingPages.rendered} rendered, ${dedupStats.landingPages.collapsed} duplicates collapsed)`);
console.log(`  slideshare     ${String(report.slideshare.files).padStart(4)} files   (from ${dedupStats.slideshare.rendered} rendered, ${dedupStats.slideshare.collapsed} duplicates collapsed)`);
console.log(`  rss            not exported — ${report.rss.endpoint}`);
console.log(`\n  output: ${DRY ? "(dry run, nothing written)" : "exports/"}`);
